-- iKontrol clean database backup
-- Source: ikontrol20_clean
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS `ikontrol_activity_logs`;
CREATE TABLE `ikontrol_activity_logs` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `created_at` datetime NOT NULL,   `created_by` int(11) NOT NULL,   `action` enum('created','updated','deleted','bitbucket_notification_received','github_notification_received') NOT NULL,   `log_type` varchar(30) NOT NULL,   `log_type_title` mediumtext NOT NULL,   `log_type_id` int(11) NOT NULL DEFAULT 0,   `changes` mediumtext DEFAULT NULL,   `log_for` varchar(30) NOT NULL DEFAULT '0',   `log_for_id` int(11) NOT NULL DEFAULT 0,   `log_for2` varchar(30) DEFAULT NULL,   `log_for_id2` int(11) DEFAULT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`),   KEY `log_for` (`log_for`,`log_for_id`),   KEY `log_for2` (`log_for2`,`log_for_id2`),   KEY `log_type` (`log_type`,`log_type_id`),   KEY `created_by` (`created_by`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_announcements`;
CREATE TABLE `ikontrol_announcements` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `description` mediumtext NOT NULL,   `start_date` date NOT NULL,   `end_date` date NOT NULL,   `created_by` int(11) NOT NULL,   `share_with` mediumtext DEFAULT NULL,   `created_at` datetime NOT NULL,   `files` text NOT NULL,   `read_by` mediumtext DEFAULT NULL,   `deleted` int(11) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`),   KEY `created_by` (`created_by`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_app_schema_versions`;
