DROP TABLE IF EXISTS `ikontrol_article_helpful_status`;
CREATE TABLE `ikontrol_article_helpful_status` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `article_id` int(11) NOT NULL,   `status` enum('yes','no') NOT NULL,   `created_by` int(11) NOT NULL DEFAULT 0,   `created_at` datetime NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_attendance`;
CREATE TABLE `ikontrol_attendance` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `status` enum('incomplete','pending','approved','rejected','deleted') NOT NULL DEFAULT 'incomplete',   `user_id` int(11) NOT NULL,   `in_time` datetime NOT NULL,   `out_time` datetime DEFAULT NULL,   `checked_by` int(11) DEFAULT NULL,   `note` text DEFAULT NULL,   `checked_at` datetime DEFAULT NULL,   `reject_reason` text DEFAULT NULL,   `deleted` int(11) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`),   KEY `user_id` (`user_id`),   KEY `checked_by` (`checked_by`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
