DROP TABLE IF EXISTS `ikontrol_checklist_template`;
CREATE TABLE `ikontrol_checklist_template` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
