DROP TABLE IF EXISTS `ikontrol_clients`;
CREATE TABLE `ikontrol_clients` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `company_name` varchar(150) NOT NULL,   `type` enum('organization','person') NOT NULL DEFAULT 'organization',   `address` text DEFAULT NULL,   `city` varchar(50) DEFAULT NULL,   `state` varchar(50) DEFAULT NULL,   `zip` varchar(50) DEFAULT NULL,   `country` varchar(50) DEFAULT NULL,   `created_date` datetime DEFAULT NULL,   `website` text DEFAULT NULL,   `phone` varchar(20) DEFAULT NULL,   `currency_symbol` varchar(20) DEFAULT NULL,   `starred_by` mediumtext NOT NULL,   `group_ids` text NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   `is_lead` tinyint(1) NOT NULL DEFAULT 0,   `lead_status_id` int(11) NOT NULL,   `owner_id` int(11) NOT NULL,   `created_by` int(11) NOT NULL,   `sort` int(11) NOT NULL DEFAULT 0,   `lead_source_id` int(11) NOT NULL,   `last_lead_status` text NOT NULL,   `client_migration_date` date DEFAULT NULL,   `vat_number` text DEFAULT NULL,   `gst_number` text DEFAULT NULL,   `stripe_customer_id` text NOT NULL,   `stripe_card_ending_digit` int(11) NOT NULL,   `currency` varchar(3) DEFAULT NULL,   `disable_online_payment` tinyint(1) NOT NULL DEFAULT 0,   `labels` text DEFAULT NULL,   `managers` text NOT NULL,   PRIMARY KEY (`id`),   KEY `owner_id` (`owner_id`),   KEY `created_by` (`created_by`),   KEY `lead_source_id` (`lead_source_id`),   KEY `is_lead` (`is_lead`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_client_groups`;
CREATE TABLE `ikontrol_client_groups` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
