rce_draft_id`),   KEY `idx_fiscal_document_invoice_status` (`invoice_id`,`status`,`deleted`),   KEY `idx_fiscal_document_snapshot` (`invoice_id`,`source_snapshot_hash`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
