ext NOT NULL,   `number_year` int(11) DEFAULT NULL,   `number_sequence` int(11) DEFAULT NULL,   `created_by` int(11) NOT NULL,   PRIMARY KEY (`id`),   KEY `status` (`status`),   KEY `due_date` (`due_date`),   KEY `client_id` (`client_id`),   KEY `project_id` (`project_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
