CREATE TABLE `ikontrol_leave_applications` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `leave_type_id` int(11) NOT NULL,   `start_date` date NOT NULL,   `end_date` date NOT NULL,   `total_hours` decimal(7,2) NOT NULL,   `total_days` decimal(5,2) NOT NULL,   `applicant_id` int(11) NOT NULL,   `reason` mediumtext NOT NULL,   `status` enum('pending','approved','rejected','canceled') NOT NULL DEFAULT 'pending',   `created_at` datetime NOT NULL,   `created_by` int(11) NOT NULL,   `checked_at` datetime DEFAULT NULL,   `checked_by` int(11) NOT NULL DEFAULT 0,   `files` text NOT NULL,   `deleted` int(11) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`),   KEY `leave_type_id` (`leave_type_id`),   KEY `user_id` (`applicant_id`),   KEY `checked_by` (`checked_by`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_leave_types`;
CREATE TABLE `ikontrol_leave_types` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` varchar(100) NOT NULL,   `status` enum('active','inactive') NOT NULL DEFAULT 'active',   `color` varchar(7) NOT NULL,   `description` text DEFAULT NULL,   `deleted` int(11) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_legacy_import_batches`;
CREATE TABLE `ikontrol_legacy_import_batches` (   `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,   `source_system` varchar(50) NOT NULL,   `source_database` varchar(150) DEFAULT NULL,   `source_owner_id` varchar(100) DEFAULT NULL,   `source_owner_key` varchar(150) DEFAULT NULL,   `entity_scope` varchar(50) NOT NULL,   `source_backup_name` varchar(255) DEFAULT NULL,   `source_backup_hash` char(64) DEFAULT NULL,   `status` varchar(30) NOT NULL DEFAULT 'pending',   `started_at` datetime DEFAULT NULL,   `completed_at` datetime DEFAULT NULL,   `created_by` int(10) unsigned DEFAULT NULL,   `summary_json` longtext DEFAULT NULL,   `error_message` longtext DEFAULT NULL,   `created_at` datetime NOT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   KEY `idx_legacy_batch_source_owner` (`source_system`,`source_owner_key`),   KEY `idx_legacy_batch_status` (`status`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_legacy_import_mappings`;
CREATE TABLE `ikontrol_legacy_import_mappings` (   `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,   `import_batch_id` bigint(20) unsigned NOT NULL,   `source_system` varchar(50) NOT NULL,   `source_table` varchar(100) NOT NULL,   `source_owner_id` varchar(100) NOT NULL DEFAULT '',   `source_id` varchar(100) NOT NULL,   `destination_table` varchar(100) DEFAULT NULL,   `destination_id` varchar(100) DEFAULT NULL,   `source_hash` char(64) DEFAULT NULL,   `destination_hash` char(64) DEFAULT NULL,   `status` varchar(30) NOT NULL DEFAULT 'pending',   `action` varchar(30) DEFAULT NULL,   `warnings_json` longtext DEFAULT NULL,   `source_snapshot_json` longtext DEFAULT NULL,   `imported_at` datetime DEFAULT NULL,   `created_at` datetime NOT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `uq_legacy_mapping_source` (`source_system`,`source_table`,`source_owner_id`,`source_id`),   KEY `idx_legacy_mapping_batch` (`import_batch_id`),   KEY `idx_legacy_mapping_destination` (`destination_table`,`destination_id`),   KEY `idx_legacy_mapping_status` (`status`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_likes`;
CREATE TABLE `ikontrol_likes` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `project_comment_id` int(11) NOT NULL,   `created_by` int(11) NOT NULL,   `created_at` datetime NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_messages`;
CREATE TABLE `ikontrol_messages` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `subject` varchar(255) NOT NULL DEFAULT 'Untitled',   `message` mediumtext NOT NULL,   `created_at` datetime NOT NULL,   `from_user_id` int(11) NOT NULL,   `to_user_id` int(11) NOT NULL,   `status` enum('unread','read') NOT NULL DEFAULT 'unread',   `message_id` int(11) NOT NULL DEFAULT 0,   `deleted` int(11) NOT NULL DEFAULT 0,   `files` longtext NOT NULL,   `deleted_by_users` text NOT NULL,   PRIMARY KEY (`id`),   KEY `message_from` (`from_user_id`),   KEY `message_to` (`to_user_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_migrations`;
CREATE TABLE `ikontrol_migrations` (   `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,   `version` varchar(255) NOT NULL,   `class` varchar(255) NOT NULL,   `group` varchar(255) NOT NULL,   `namespace` varchar(255) NOT NULL,   `time` int(11) NOT NULL,   `batch` int(11) unsigned NOT NULL,   PRIMARY KEY (`id`) ) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_milestones`;
CREATE TABLE `ikontrol_milestones` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `project_id` int(11) NOT NULL,   `due_date` date NOT NULL,   `description` text NOT NULL,   `deleted` tinyint(4) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_notes`;
CREATE TABLE `ikontrol_notes` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `created_by` int(11) NOT NULL,   `created_at` datetime NOT NULL,   `title` text NOT NULL,   `description` mediumtext DEFAULT NULL,   `project_id` int(11) NOT NULL DEFAULT 0,   `client_id` int(11) NOT NULL DEFAULT 0,   `user_id` int(11) NOT NULL DEFAULT 0,   `labels` text DEFAULT NULL,   `files` mediumtext NOT NULL,   `is_public` tinyint(1) NOT NULL DEFAULT 0,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   `category_id` int(11) DEFAULT 0,   `color` varchar(14) NOT NULL,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_note_category`;
CREATE TABLE `ikontrol_note_category` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `name` text DEFAULT NULL,   `user_id` int(11) NOT NULL DEFAULT 0,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_notifications`;
CREATE TABLE `ikontrol_notifications` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `user_id` int(11) NOT NULL,   `description` longtext NOT NULL,   `created_at` datetime NOT NULL,   `notify_to` mediumtext NOT NULL,   `read_by` mediumtext NOT NULL,   `event` varchar(250) NOT NULL,   `project_id` int(11) NOT NULL,   `task_id` int(11) NOT NULL,   `project_comment_id` int(11) NOT NULL,   `ticket_id` int(11) NOT NULL,   `ticket_comment_id` int(11) NOT NULL,   `project_file_id` int(11) NOT NULL,   `leave_id` int(11) NOT NULL,   `post_id` int(11) NOT NULL,   `to_user_id` int(11) NOT NULL,   `activity_log_id` int(11) NOT NULL,   `client_id` int(11) NOT NULL,   `lead_id` int(11) NOT NULL,   `invoice_payment_id` int(11) NOT NULL,   `invoice_id` int(11) NOT NULL,   `estimate_id` int(11) NOT NULL,   `contract_id` int(11) NOT NULL,   `order_id` int(11) NOT NULL,   `estimate_request_id` int(11) NOT NULL,   `actual_message_id` int(11) NOT NULL,   `parent_message_id` int(11) NOT NULL,   `event_id` int(11) NOT NULL,   `announcement_id` int(11) NOT NULL,   `proposal_id` int(11) NOT NULL,   `estimate_comment_id` int(11) NOT NULL,   `subscription_id` int(11) NOT NULL,   `expense_id` int(11) NOT NULL,   `proposal_comment_id` int(11) NOT NULL,   `reminder_log_id` int(11) NOT NULL,   `deleted` int(11) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`),   KEY `user_id` (`user_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_notification_settings`;
CREATE TABLE `ikontrol_notification_settings` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `event` varchar(250) NOT NULL,   `category` varchar(50) NOT NULL,   `enable_email` int(11) NOT NULL DEFAULT 0,   `enable_web` int(11) NOT NULL DEFAULT 0,   `enable_slack` int(11) NOT NULL DEFAULT 0,   `notify_to_team` text NOT NULL,   `notify_to_team_members` text NOT NULL,   `notify_to_terms` text NOT NULL,   `sort` int(11) NOT NULL,   `deleted` int(11) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`),   KEY `event` (`event`) ) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_orders`;
CREATE TABLE `ikontrol_orders` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `client_id` int(11) NOT NULL,   `order_date` date NOT NULL,   `note` mediumtext DEFAULT NULL,   `status_id` int(11) NOT NULL,   `tax_id` int(11) NOT NULL DEFAULT 0,   `tax_id2` int(11) NOT NULL DEFAULT 0,   `discount_amount` double NOT NULL,   `discount_amount_type` enum('percentage','fixed_amount') NOT NULL,   `discount_type` enum('before_tax','after_tax') NOT NULL,   `created_by` int(11) NOT NULL DEFAULT 0,   `project_id` int(11) NOT NULL DEFAULT 0,   `files` longtext NOT NULL,   `company_id` int(11) NOT NULL DEFAULT 0,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   `created_by_hash` text NOT NULL,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_order_items`;
CREATE TABLE `ikontrol_order_items` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `description` text DEFAULT NULL,   `quantity` double NOT NULL,   `unit_type` varchar(20) NOT NULL DEFAULT '',   `rate` double NOT NULL,   `total` double NOT NULL,   `order_id` int(11) NOT NULL,   `created_by` int(11) NOT NULL,   `item_id` int(11) NOT NULL DEFAULT 0,   `sort` int(11) NOT NULL DEFAULT 0,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   `created_by_hash` text NOT NULL,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_order_status`;
CREATE TABLE `ikontrol_order_status` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` varchar(100) NOT NULL,   `color` varchar(7) NOT NULL,   `sort` int(11) NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_pages`;
CREATE TABLE `ikontrol_pages` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text DEFAULT NULL,   `content` longtext DEFAULT NULL,   `slug` text DEFAULT NULL,   `status` enum('active','inactive') NOT NULL DEFAULT 'active',   `internal_use_only` tinyint(1) NOT NULL DEFAULT 0,   `visible_to_team_members_only` tinyint(1) NOT NULL DEFAULT 0,   `visible_to_clients_only` tinyint(1) NOT NULL DEFAULT 0,   `full_width` tinyint(1) NOT NULL DEFAULT 0,   `hide_topbar` tinyint(1) NOT NULL DEFAULT 0,   `deleted` int(11) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
