DROP TABLE IF EXISTS `ikontrol_project_members`;
CREATE TABLE `ikontrol_project_members` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `user_id` int(11) NOT NULL,   `project_id` int(11) NOT NULL,   `is_leader` tinyint(1) DEFAULT 0,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`),   KEY `user_id` (`user_id`),   KEY `project_id` (`project_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
