DROP TABLE IF EXISTS `ikontrol_project_time`;
CREATE TABLE `ikontrol_project_time` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `project_id` int(11) NOT NULL,   `user_id` int(11) NOT NULL,   `start_time` datetime NOT NULL,   `end_time` datetime DEFAULT NULL,   `hours` float NOT NULL,   `status` enum('open','logged','approved') NOT NULL DEFAULT 'logged',   `note` text DEFAULT NULL,   `task_id` int(11) NOT NULL DEFAULT 0,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_proposals`;
