DROP TABLE IF EXISTS `ikontrol_proposal_comments`;
CREATE TABLE `ikontrol_proposal_comments` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `created_by` int(11) NOT NULL,   `created_at` datetime NOT NULL,   `description` mediumtext NOT NULL,   `proposal_id` int(11) NOT NULL DEFAULT 0,   `files` longtext DEFAULT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_proposal_items`;
CREATE TABLE `ikontrol_proposal_items` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `description` text DEFAULT NULL,   `quantity` double NOT NULL,   `unit_type` varchar(20) NOT NULL DEFAULT '',   `rate` double NOT NULL,   `total` double NOT NULL,   `sort` int(11) NOT NULL DEFAULT 0,   `proposal_id` int(11) NOT NULL,   `item_id` int(11) NOT NULL DEFAULT 0,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_proposal_templates`;
CREATE TABLE `ikontrol_proposal_templates` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` varchar(50) NOT NULL,   `template` mediumtext DEFAULT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_reminder_logs`;
CREATE TABLE `ikontrol_reminder_logs` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `context` varchar(255) NOT NULL,   `context_id` int(11) NOT NULL,   `reminder_event` varchar(255) DEFAULT NULL,   `notification_status` enum('draft','completed') NOT NULL DEFAULT 'draft',   `reminder_date` date DEFAULT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_reminder_settings`;
CREATE TABLE `ikontrol_reminder_settings` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `type` varchar(20) NOT NULL DEFAULT 'app',   `context` text NOT NULL,   `reminder_event` text NOT NULL,   `reminder1` int(11) DEFAULT NULL,   `reminder2` int(11) DEFAULT NULL,   `reminder3` int(11) DEFAULT NULL,   `reminder4` int(11) DEFAULT NULL,   `reminder5` int(11) DEFAULT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_roles`;
CREATE TABLE `ikontrol_roles` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` varchar(100) NOT NULL,   `permissions` mediumtext DEFAULT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_sale_fiscal_pricing_preparations`;
CREATE TABLE `ikontrol_sale_fiscal_pricing_preparations` (   `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,   `invoice_id` int(10) unsigned NOT NULL,   `issuer_profile_id` int(10) unsigned NOT NULL,   `receiver_profile_id` int(10) unsigned DEFAULT NULL,   `fiscal_series_id` int(10) unsigned DEFAULT NULL,   `pricing_mode` varchar(20) NOT NULL,   `administrative_subtotal` decimal(18,2) NOT NULL DEFAULT 0.00,   `administrative_discount` decimal(18,2) NOT NULL DEFAULT 0.00,   `administrative_tax_total` decimal(18,2) NOT NULL DEFAULT 0.00,   `administrative_total` decimal(18,2) NOT NULL DEFAULT 0.00,   `estimated_fiscal_base` decimal(18,2) NOT NULL DEFAULT 0.00,   `estimated_fiscal_discount` decimal(18,2) NOT NULL DEFAULT 0.00,   `estimated_fiscal_tax_total` decimal(18,2) NOT NULL DEFAULT 0.00,   `estimated_fiscal_total` decimal(18,2) NOT NULL DEFAULT 0.00,   `difference_amount` decimal(18,2) NOT NULL DEFAULT 0.00,   `previous_balance` decimal(18,2) NOT NULL DEFAULT 0.00,   `estimated_balance` decimal(18,2) NOT NULL DEFAULT 0.00,   `payment_total_snapshot` decimal(18,2) NOT NULL DEFAULT 0.00,   `status` varchar(30) NOT NULL DEFAULT 'simulated',   `requires_confirmation` tinyint(1) NOT NULL DEFAULT 0,   `confirmed_by` int(10) unsigned DEFAULT NULL,   `confirmed_at` datetime DEFAULT NULL,   `applied_to_sale` tinyint(1) NOT NULL DEFAULT 0,   `applied_by` int(10) unsigned DEFAULT NULL,   `applied_at` datetime DEFAULT NULL,   `calculation_payload` longtext DEFAULT NULL,   `created_by` int(10) unsigned DEFAULT NULL,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   KEY `invoice_id_status` (`invoice_id`,`status`),   KEY `issuer_profile_id_created_at` (`issuer_profile_id`,`created_at`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_sat_cfdi_uses`;
CREATE TABLE `ikontrol_sat_cfdi_uses` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `code` varchar(10) NOT NULL,   `description` varchar(255) NOT NULL,   `applies_to_individual` tinyint(1) NOT NULL DEFAULT 0,   `applies_to_company` tinyint(1) NOT NULL DEFAULT 0,   `valid_from` date DEFAULT NULL,   `valid_to` date DEFAULT NULL,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `code` (`code`),   KEY `valid_from_valid_to` (`valid_from`,`valid_to`),   KEY `is_active` (`is_active`) ) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_sat_currencies`;
CREATE TABLE `ikontrol_sat_currencies` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `code` char(3) NOT NULL,   `name` varchar(120) NOT NULL,   `requires_exchange_rate` tinyint(1) NOT NULL DEFAULT 1,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `uq_sat_currencies_code` (`code`) ) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_sat_payment_forms`;
CREATE TABLE `ikontrol_sat_payment_forms` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `code` varchar(3) NOT NULL,   `name` varchar(120) NOT NULL,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `uq_sat_payment_forms_code` (`code`) ) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_sat_payment_methods`;
CREATE TABLE `ikontrol_sat_payment_methods` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `code` varchar(3) NOT NULL,   `name` varchar(120) NOT NULL,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `uq_sat_payment_methods_code` (`code`) ) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_sat_product_service_keys`;
CREATE TABLE `ikontrol_sat_product_service_keys` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `code` varchar(8) NOT NULL,   `description` varchar(500) NOT NULL,   `valid_from` date DEFAULT NULL,   `valid_to` date DEFAULT NULL,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `source_version` varchar(80) DEFAULT NULL,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `code` (`code`),   KEY `description` (`description`),   KEY `is_active_valid_from_valid_to` (`is_active`,`valid_from`,`valid_to`) ) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_sat_tax_codes`;
CREATE TABLE `ikontrol_sat_tax_codes` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `code` varchar(3) NOT NULL,   `name` varchar(30) NOT NULL,   `description` varchar(255) DEFAULT NULL,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `code` (`code`),   KEY `is_active` (`is_active`) ) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_sat_tax_factor_types`;
CREATE TABLE `ikontrol_sat_tax_factor_types` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `code` varchar(20) NOT NULL,   `name` varchar(30) NOT NULL,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `code` (`code`),   KEY `is_active` (`is_active`) ) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_sat_tax_object_codes`;
CREATE TABLE `ikontrol_sat_tax_object_codes` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `code` varchar(2) NOT NULL,   `description` varchar(255) NOT NULL,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `valid_from` date DEFAULT NULL,   `valid_to` date DEFAULT NULL,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `code` (`code`),   KEY `is_active` (`is_active`) ) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_sat_tax_regimes`;
CREATE TABLE `ikontrol_sat_tax_regimes` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `code` varchar(10) NOT NULL,   `description` varchar(255) NOT NULL,   `applies_to_individual` tinyint(1) NOT NULL DEFAULT 0,   `applies_to_company` tinyint(1) NOT NULL DEFAULT 0,   `valid_from` date DEFAULT NULL,   `valid_to` date DEFAULT NULL,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `code` (`code`),   KEY `valid_from_valid_to` (`valid_from`,`valid_to`),   KEY `is_active` (`is_active`) ) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_sat_unit_keys`;
CREATE TABLE `ikontrol_sat_unit_keys` (   `id` int(10) unsigned NOT NULL AUTO_INCREMENT,   `code` varchar(10) NOT NULL,   `name` varchar(120) NOT NULL,   `description` varchar(500) DEFAULT NULL,   `symbol` varchar(30) DEFAULT NULL,   `valid_from` date DEFAULT NULL,   `valid_to` date DEFAULT NULL,   `is_active` tinyint(1) NOT NULL DEFAULT 1,   `source_version` varchar(80) DEFAULT NULL,   `created_at` datetime DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   UNIQUE KEY `code` (`code`),   KEY `name` (`name`),   KEY `is_active_valid_from_valid_to` (`is_active`,`valid_from`,`valid_to`) ) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `ikontrol_settings`;
CREATE TABLE `ikontrol_settings` (   `setting_name` varchar(100) NOT NULL,   `setting_value` mediumtext NOT NULL,   `type` varchar(20) NOT NULL DEFAULT 'app',   `deleted` tinyint(1) NOT NULL DEFAULT 0,   UNIQUE KEY `setting_name` (`setting_name`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_social_links`;
CREATE TABLE `ikontrol_social_links` (   `id` int(11) NOT NULL,   `user_id` int(11) NOT NULL,   `facebook` text DEFAULT NULL,   `twitter` text DEFAULT NULL,   `linkedin` text DEFAULT NULL,   `googleplus` text DEFAULT NULL,   `digg` text DEFAULT NULL,   `youtube` text DEFAULT NULL,   `pinterest` text DEFAULT NULL,   `instagram` text DEFAULT NULL,   `github` text DEFAULT NULL,   `tumblr` text DEFAULT NULL,   `vine` text DEFAULT NULL,   `whatsapp` text DEFAULT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_stripe_ipn`;
CREATE TABLE `ikontrol_stripe_ipn` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `session_id` text NOT NULL,   `verification_code` text NOT NULL,   `payment_verification_code` text NOT NULL,   `invoice_id` int(11) NOT NULL,   `contact_user_id` int(11) NOT NULL,   `client_id` int(11) NOT NULL,   `payment_method_id` int(11) NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   `setup_intent` text NOT NULL,   `subscription_id` int(11) NOT NULL,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_subscriptions`;
CREATE TABLE `ikontrol_subscriptions` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `client_id` int(11) NOT NULL,   `bill_date` date DEFAULT NULL,   `end_date` date DEFAULT NULL,   `note` mediumtext DEFAULT NULL,   `labels` text NOT NULL,   `status` enum('draft','pending','active','cancelled') NOT NULL DEFAULT 'draft',   `payment_status` enum('success','failed') NOT NULL DEFAULT 'success',   `tax_id` int(11) NOT NULL DEFAULT 0,   `tax_id2` int(11) NOT NULL DEFAULT 0,   `repeat_every` int(11) NOT NULL DEFAULT 1,   `repeat_type` enum('days','weeks','months','years') DEFAULT NULL,   `no_of_cycles` int(11) NOT NULL DEFAULT 0,   `next_recurring_date` date DEFAULT NULL,   `no_of_cycles_completed` int(11) NOT NULL DEFAULT 0,   `cancelled_at` datetime DEFAULT NULL,   `cancelled_by` int(11) NOT NULL,   `files` mediumtext NOT NULL,   `company_id` int(11) NOT NULL DEFAULT 0,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   `type` enum('app','stripe') NOT NULL DEFAULT 'app',   `stripe_subscription_id` text NOT NULL,   `stripe_product_id` text NOT NULL,   `stripe_product_price_id` text NOT NULL,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_subscription_items`;
CREATE TABLE `ikontrol_subscription_items` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `description` text DEFAULT NULL,   `quantity` double NOT NULL,   `unit_type` varchar(20) NOT NULL DEFAULT '',   `rate` double NOT NULL,   `total` double NOT NULL,   `sort` int(11) NOT NULL DEFAULT 0,   `subscription_id` int(11) NOT NULL,   `item_id` int(11) NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_tasks`;
CREATE TABLE `ikontrol_tasks` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `description` mediumtext DEFAULT NULL,   `project_id` int(11) NOT NULL,   `milestone_id` int(11) NOT NULL DEFAULT 0,   `assigned_to` int(11) NOT NULL,   `deadline` datetime DEFAULT NULL,   `labels` text DEFAULT NULL,   `points` tinyint(4) NOT NULL DEFAULT 1,   `status` enum('to_do','in_progress','done') NOT NULL DEFAULT 'to_do',   `status_id` int(11) NOT NULL,   `priority_id` int(11) NOT NULL,   `start_date` datetime DEFAULT NULL,   `collaborators` text NOT NULL,   `sort` int(11) NOT NULL DEFAULT 0,   `recurring` tinyint(1) NOT NULL DEFAULT 0,   `repeat_every` int(11) NOT NULL DEFAULT 0,   `repeat_type` enum('days','weeks','months','years') DEFAULT NULL,   `no_of_cycles` int(11) NOT NULL DEFAULT 0,   `recurring_task_id` int(11) NOT NULL DEFAULT 0,   `no_of_cycles_completed` int(11) NOT NULL DEFAULT 0,   `created_date` date DEFAULT NULL,   `blocking` text NOT NULL,   `blocked_by` text NOT NULL,   `parent_task_id` int(11) NOT NULL,   `next_recurring_date` date DEFAULT NULL,   `reminder_date` date DEFAULT NULL,   `ticket_id` int(11) NOT NULL,   `status_changed_at` datetime DEFAULT NULL,   `deleted` tinyint(4) NOT NULL DEFAULT 0,   `expense_id` int(11) NOT NULL DEFAULT 0,   `subscription_id` int(11) NOT NULL DEFAULT 0,   `proposal_id` int(11) NOT NULL DEFAULT 0,   `contract_id` int(11) NOT NULL DEFAULT 0,   `order_id` int(11) NOT NULL DEFAULT 0,   `estimate_id` int(11) NOT NULL DEFAULT 0,   `invoice_id` int(11) NOT NULL DEFAULT 0,   `lead_id` int(11) NOT NULL DEFAULT 0,   `client_id` int(11) NOT NULL DEFAULT 0,   `context` enum('project','client','lead','invoice','estimate','order','contract','proposal','subscription','ticket','expense','general') NOT NULL DEFAULT 'general',   `created_by` int(11) DEFAULT NULL,   PRIMARY KEY (`id`),   KEY `status_id` (`status_id`),   KEY `priority_id` (`priority_id`),   KEY `sort` (`sort`),   KEY `project_id` (`project_id`),   KEY `milestone_id` (`milestone_id`),   KEY `assigned_to` (`assigned_to`),   KEY `ticket_id` (`ticket_id`),   KEY `client_id` (`client_id`),   KEY `invoice_id` (`invoice_id`),   KEY `estimate_id` (`estimate_id`),   KEY `order_id` (`order_id`),   KEY `contract_id` (`contract_id`),   KEY `proposal_id` (`proposal_id`),   KEY `subscription_id` (`subscription_id`),   KEY `expense_id` (`expense_id`),   KEY `lead_id` (`lead_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_task_priority`;
CREATE TABLE `ikontrol_task_priority` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` varchar(100) NOT NULL,   `icon` varchar(20) NOT NULL,   `color` varchar(7) NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_task_status`;
CREATE TABLE `ikontrol_task_status` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` varchar(100) NOT NULL,   `key_name` varchar(100) NOT NULL,   `color` varchar(7) NOT NULL,   `sort` int(11) NOT NULL,   `hide_from_kanban` tinyint(1) NOT NULL DEFAULT 0,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   `hide_from_non_project_related_tasks` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_taxes`;
CREATE TABLE `ikontrol_taxes` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` tinytext NOT NULL,   `percentage` double NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   `stripe_tax_id` text NOT NULL,   `sat_tax_code_id` int(10) unsigned DEFAULT NULL,   `fiscal_tax_type` varchar(20) DEFAULT NULL,   `factor_type_id` int(10) unsigned DEFAULT NULL,   `xml_rate` decimal(18,6) DEFAULT NULL,   `xml_quota` decimal(18,6) DEFAULT NULL,   `is_fiscal_ready` tinyint(1) DEFAULT 0,   `use_for_administrative` tinyint(1) DEFAULT 1,   `use_for_fiscal` tinyint(1) DEFAULT 0,   `fiscal_notes` text DEFAULT NULL,   `updated_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`) ) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_team`;
CREATE TABLE `ikontrol_team` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `members` mediumtext NOT NULL,   `deleted` int(11) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_team_member_job_info`;
CREATE TABLE `ikontrol_team_member_job_info` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `user_id` int(11) NOT NULL,   `date_of_hire` date DEFAULT NULL,   `deleted` int(11) NOT NULL DEFAULT 0,   `salary` double NOT NULL DEFAULT 0,   `salary_term` varchar(20) DEFAULT NULL,   PRIMARY KEY (`id`),   KEY `user_id` (`user_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_tickets`;
CREATE TABLE `ikontrol_tickets` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `client_id` int(11) NOT NULL,   `project_id` int(11) NOT NULL DEFAULT 0,   `ticket_type_id` int(11) NOT NULL,   `title` text NOT NULL,   `created_by` int(11) NOT NULL,   `requested_by` int(11) NOT NULL DEFAULT 0,   `created_at` datetime NOT NULL,   `status` enum('new','client_replied','open','closed') NOT NULL DEFAULT 'new',   `last_activity_at` datetime DEFAULT NULL,   `assigned_to` int(11) NOT NULL DEFAULT 0,   `creator_name` varchar(100) NOT NULL,   `creator_email` varchar(255) NOT NULL,   `labels` text DEFAULT NULL,   `task_id` int(11) NOT NULL,   `closed_at` datetime NOT NULL,   `merged_with_ticket_id` int(11) NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   `cc_contacts_and_emails` text DEFAULT NULL,   `client_last_activity_at` datetime DEFAULT NULL,   PRIMARY KEY (`id`),   KEY `client_id` (`client_id`),   KEY `ticket_type_id` (`ticket_type_id`),   KEY `assigned_to` (`assigned_to`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_ticket_comments`;
CREATE TABLE `ikontrol_ticket_comments` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `created_by` int(11) NOT NULL,   `created_at` datetime NOT NULL,   `description` mediumtext NOT NULL,   `ticket_id` int(11) NOT NULL,   `files` longtext DEFAULT NULL,   `is_note` tinyint(1) NOT NULL DEFAULT 0,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_ticket_templates`;
CREATE TABLE `ikontrol_ticket_templates` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `description` mediumtext NOT NULL,   `ticket_type_id` int(11) NOT NULL,   `private` mediumtext NOT NULL,   `created_by` int(11) NOT NULL,   `created_at` datetime NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_ticket_types`;
CREATE TABLE `ikontrol_ticket_types` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `title` text NOT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_to_do`;
CREATE TABLE `ikontrol_to_do` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `created_by` int(11) NOT NULL,   `created_at` datetime NOT NULL,   `title` text NOT NULL,   `description` mediumtext DEFAULT NULL,   `labels` text DEFAULT NULL,   `status` enum('to_do','done') NOT NULL DEFAULT 'to_do',   `start_date` date DEFAULT NULL,   `deleted` tinyint(1) NOT NULL DEFAULT 0,   `files` mediumtext NOT NULL,   `sort` double NOT NULL DEFAULT 1,   PRIMARY KEY (`id`),   KEY `created_by` (`created_by`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_users`;
CREATE TABLE `ikontrol_users` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `first_name` varchar(50) NOT NULL,   `last_name` varchar(50) NOT NULL,   `user_type` enum('staff','client','lead') NOT NULL DEFAULT 'client',   `is_admin` tinyint(1) NOT NULL DEFAULT 0,   `role_id` int(11) NOT NULL DEFAULT 0,   `email` varchar(255) NOT NULL,   `password` varchar(255) DEFAULT NULL,   `image` text DEFAULT NULL,   `status` enum('active','inactive') NOT NULL DEFAULT 'active',   `message_checked_at` datetime DEFAULT NULL,   `client_id` int(11) NOT NULL DEFAULT 0,   `notification_checked_at` datetime DEFAULT NULL,   `is_primary_contact` tinyint(1) NOT NULL DEFAULT 0,   `job_title` varchar(100) NOT NULL DEFAULT 'Untitled',   `disable_login` tinyint(1) NOT NULL DEFAULT 0,   `note` mediumtext DEFAULT NULL,   `address` text DEFAULT NULL,   `alternative_address` text DEFAULT NULL,   `phone` varchar(20) DEFAULT NULL,   `alternative_phone` varchar(20) DEFAULT NULL,   `dob` date DEFAULT NULL,   `ssn` varchar(20) DEFAULT NULL,   `gender` enum('male','female','other') DEFAULT NULL,   `sticky_note` mediumtext DEFAULT NULL,   `skype` text DEFAULT NULL,   `language` varchar(50) NOT NULL,   `enable_web_notification` tinyint(1) NOT NULL DEFAULT 1,   `enable_email_notification` tinyint(1) NOT NULL DEFAULT 1,   `created_at` datetime DEFAULT NULL,   `last_online` datetime DEFAULT NULL,   `requested_account_removal` tinyint(1) NOT NULL DEFAULT 0,   `client_permissions` text DEFAULT NULL,   `deleted` int(11) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`),   KEY `user_type` (`user_type`),   KEY `email` (`email`),   KEY `client_id` (`client_id`),   KEY `deleted` (`deleted`) ) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
DROP TABLE IF EXISTS `ikontrol_verification`;
CREATE TABLE `ikontrol_verification` (   `id` int(11) NOT NULL AUTO_INCREMENT,   `created_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),   `type` enum('invoice_payment','reset_password','verify_email','invitation') NOT NULL,   `code` varchar(10) NOT NULL,   `params` text NOT NULL,   `deleted` int(11) NOT NULL DEFAULT 0,   PRIMARY KEY (`id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
SET FOREIGN_KEY_CHECKS=1;
